<?php namespace App\Policies; use App\Models\User; use App\Models\AiChatConversation; class AiChatConversationPolicy { public function viewAny(User $user) { return true; } public function view(User $user, AiChatConversation $conversation) { if ($user->hasRole(["admin", "hr"])) return true; return $user->id === $conversation->user_id; } public function update(User $user, AiChatConversation $conversation) { return $user->id === $conversation->user_id; } public function delete(User $user, AiChatConversation $conversation) { return $user->id === $conversation->user_id; } }